"""Torch SDPA fallback for flash attention on non-SM90 devices."""


import math
from typing import Callable, Optional, Tuple

import torch
import torch.nn.functional as F

from kestrel_kernels.fallback import warn_fallback_once
from kestrel_kernels.flash_attn.cute.mask_ids import (
    BLOCK_BIDIRECTIONAL_MASK_ID,
    WINDOWED_BLOCKDIAG_MASK_ID,
)

# D256 paged prefill uses native Metal once the sequence is long enough
# to amortize launch/tile overhead. Below this, gather+SDPA wins on MPS.
# Tried lowering to q>=16 for Qwen 8q/2kv/D256 packed prefill: native was
# 0.18x at q=16, 0.84x at q=512, and 1.41x at q=1024; keeping 1024.
_MPS_D256_PREFILL_NATIVE_MIN_Q = 1024


def _mps_ops():
    from kestrel_kernels.mps import _native as _mps_native

    return _mps_native.ops


def _is_block_bidirectional(mask_mod: Optional[Callable]) -> bool:
    if mask_mod is None:
        return False
    return getattr(mask_mod, "__cute_hash__", None) == BLOCK_BIDIRECTIONAL_MASK_ID


def _is_windowed_blockdiag(mask_mod: Optional[Callable]) -> bool:
    if mask_mod is None:
        return False
    return getattr(mask_mod, "__cute_hash__", None) == WINDOWED_BLOCKDIAG_MASK_ID


def _prepare_kv_for_sdpa(
    *,
    k: torch.Tensor,
    v: torch.Tensor,
    target_dtype: torch.dtype,
    k_scale: float,
    v_scale: float,
) -> tuple[torch.Tensor, torch.Tensor, float, float]:
    q_scale = 1.0
    out_scale = 1.0

    if k.dtype == torch.float8_e4m3fn:
        k = k.to(target_dtype)
        q_scale = float(k_scale)
    elif k.dtype != target_dtype:
        k = k.to(target_dtype)

    if v.dtype == torch.float8_e4m3fn:
        v = v.to(target_dtype)
        out_scale = float(v_scale)
    elif v.dtype != target_dtype:
        v = v.to(target_dtype)

    return k, v, q_scale, out_scale


def _index_select_first_dim(t: torch.Tensor, idx: torch.Tensor) -> torch.Tensor:
    # Torch 2.4 on Jetson lacks float8 index_select CUDA kernels.
    if t.dtype == torch.float8_e4m3fn:
        return t.view(torch.uint8).index_select(0, idx).view(torch.float8_e4m3fn)
    return t.index_select(0, idx)


def _get_block_bidi_mask(
    block_seq_ids: torch.Tensor,
    q_len: int,
    kv_len: int,
    device: torch.device,
    dtype: torch.dtype,
) -> torch.Tensor:
    """Additive mask ``[1, 1, qL, kL]`` for the block-bidirectional prefix mask:
    ``0`` where attention is allowed, ``-inf`` elsewhere. A query attends a key
    iff it is causal (``kv <= q``) OR both lie in the same image block
    (``block_seq_ids[q] == block_seq_ids[kv] >= 0``). ``block_seq_ids`` is the
    per-token image-block id for this sequence (>= kv_len entries; image-block
    id >= 0, or -1 for text). Not cached — the mask depends on the per-request
    block layout, not just ``(qL, kL)``.
    """
    kv_idx = torch.arange(kv_len, device=device, dtype=torch.int64)
    q_abs_idx = torch.arange(q_len, device=device, dtype=torch.int64) + max(kv_len - q_len, 0)
    allowed = kv_idx[None] <= q_abs_idx[:, None]
    bq = block_seq_ids[q_abs_idx]
    bk = block_seq_ids[kv_idx]
    allowed = allowed | ((bq[:, None] == bk[None, :]) & (bq[:, None] >= 0))
    mask_2d = torch.zeros((q_len, kv_len), dtype=dtype, device=device)
    mask_2d.masked_fill_(~allowed, float("-inf"))
    return mask_2d.view(1, 1, q_len, kv_len)


def _build_additive_attn_mask(
    *,
    q_len: int,
    kv_len: int,
    causal: bool,
    window_size_left: Optional[int],
    window_size_right: Optional[int],
    device: torch.device,
    block_seq_ids: Optional[torch.Tensor] = None,
    windowed_widths: Optional[tuple[int, int]] = None,
) -> Optional[torch.Tensor]:
    has_window = window_size_left is not None or window_size_right is not None
    if windowed_widths is not None:
        # Block-diagonal windowed mask: attend iff the query and key fall in the
        # same fixed-size window. Positions are the RAW packed positions (no
        # cache-prefix / causal shift): query row i is in window i // window_q,
        # key col j in window j // window_kv. Independent of causal / sliding-window
        # (a packed-window bracket declares neither).
        window_q, window_kv = int(windowed_widths[0]), int(windowed_widths[1])
        q_win = (torch.arange(q_len, device=device, dtype=torch.int64) // window_q)
        k_win = (torch.arange(kv_len, device=device, dtype=torch.int64) // window_kv)
        allowed = q_win[:, None] == k_win[None, :]
        attn_mask = torch.zeros((q_len, kv_len), dtype=torch.float32, device=device)
        attn_mask.masked_fill_(~allowed, float("-inf"))
        return attn_mask
    if not causal and block_seq_ids is None and not has_window:
        return None
    if q_len == 1 and not has_window:
        # For the decode-style single-query case, q_abs_idx = kv_len - 1, so causal
        # (and block-bidirectional OR causal) admits all keys; no
        # explicit mask is needed.
        return None

    kv_idx = torch.arange(kv_len, device=device, dtype=torch.int64)
    q_abs_idx = torch.arange(q_len, device=device, dtype=torch.int64) + max(kv_len - q_len, 0)

    if block_seq_ids is not None:
        # Block-bidirectional: causal OR same image block (id >= 0).
        allowed = kv_idx[None] <= q_abs_idx[:, None]
        bq = block_seq_ids[q_abs_idx]
        bk = block_seq_ids[kv_idx]
        allowed = allowed | ((bq[:, None] == bk[None, :]) & (bq[:, None] >= 0))
    elif causal:
        allowed = kv_idx[None] <= q_abs_idx[:, None]
    else:
        allowed = torch.ones((q_len, kv_len), dtype=torch.bool, device=device)

    if window_size_left is not None:
        allowed &= kv_idx[None] >= q_abs_idx[:, None] - int(window_size_left)
    if window_size_right is not None:
        allowed &= kv_idx[None] <= q_abs_idx[:, None] + int(window_size_right)

    attn_mask = torch.zeros((q_len, kv_len), dtype=torch.float32, device=device)
    attn_mask.masked_fill_(~allowed, float("-inf"))
    return attn_mask


def _repeat_kv_for_gqa(
    q: torch.Tensor,
    k: torch.Tensor,
    v: torch.Tensor,
    *,
    label: str,
) -> tuple[torch.Tensor, torch.Tensor]:
    if q.shape[1] == k.shape[1]:
        return k, v
    if q.shape[1] % k.shape[1] != 0:
        raise ValueError(
            f"fallback {label} requires q heads to be divisible by kv heads "
            f"(got q={q.shape[1]}, kv={k.shape[1]})"
        )
    repeat = q.shape[1] // k.shape[1]
    return k.repeat_interleave(repeat, dim=1), v.repeat_interleave(repeat, dim=1)


def _sdpa(
    *,
    q: torch.Tensor,
    k: torch.Tensor,
    v: torch.Tensor,
    attn_mask: Optional[torch.Tensor],
    softmax_scale: Optional[float],
) -> torch.Tensor:
    if attn_mask is not None and attn_mask.dtype != q.dtype:
        attn_mask = attn_mask.to(q.dtype)
    k, v = _repeat_kv_for_gqa(q, k, v, label="GQA")
    kwargs = {
        "attn_mask": attn_mask,
        "dropout_p": 0.0,
        "is_causal": False,
    }
    if softmax_scale is None:
        return F.scaled_dot_product_attention(q, k, v, **kwargs)
    try:
        return F.scaled_dot_product_attention(q, k, v, scale=float(softmax_scale), **kwargs)
    except TypeError:
        default_scale = 1.0 / math.sqrt(q.shape[-1])
        q_scaled = q if math.isclose(float(softmax_scale), default_scale) else q * (float(softmax_scale) / default_scale)
        return F.scaled_dot_product_attention(q_scaled, k, v, **kwargs)


def _attention_forward(
    *,
    q: torch.Tensor,
    k: torch.Tensor,
    v: torch.Tensor,
    q_len: int,
    kv_len: int,
    causal: bool,
    window_size_left: Optional[int],
    window_size_right: Optional[int],
    softmax_scale: Optional[float],
    block_seq_ids: Optional[torch.Tensor] = None,
    windowed_widths: Optional[tuple[int, int]] = None,
) -> torch.Tensor:
    attn_mask = _build_additive_attn_mask(
        q_len=q_len,
        kv_len=kv_len,
        causal=causal,
        window_size_left=window_size_left,
        window_size_right=window_size_right,
        device=q.device,
        block_seq_ids=block_seq_ids,
        windowed_widths=windowed_widths,
    )
    return (
        _sdpa(
            q=q,
            k=k,
            v=v,
            attn_mask=attn_mask,
            softmax_scale=softmax_scale,
        )
    )


def _dense_used_k_attention_forward(
    *,
    q: torch.Tensor,
    k: torch.Tensor,
    v: torch.Tensor,
    kv_lens: torch.Tensor,
    causal: bool,
    window_size_left: Optional[int],
    window_size_right: Optional[int],
    softmax_scale: Optional[float],
    block_seq_ids: Optional[torch.Tensor] = None,
) -> torch.Tensor:
    """Run one batched attention with a device-resident active-K mask."""
    batch_size, _num_heads, q_len, _head_dim = q.shape
    kv_len = int(k.shape[2])
    kv_lens = kv_lens.to(device=q.device)

    kv_idx = torch.arange(kv_len, device=q.device, dtype=kv_lens.dtype)
    kv_idx = kv_idx.view(1, 1, kv_len)
    q_idx = torch.arange(q_len, device=q.device, dtype=kv_lens.dtype)
    q_idx = q_idx.view(1, q_len, 1)
    q_offset = (kv_lens - q_len).clamp_min(0).view(batch_size, 1, 1)
    q_abs_idx = q_idx + q_offset

    allowed = kv_idx < kv_lens.view(batch_size, 1, 1)
    if block_seq_ids is not None:
        if block_seq_ids.ndim == 1:
            block_seq_ids = block_seq_ids.unsqueeze(0).expand(batch_size, -1)
        bq = block_seq_ids.gather(1, q_abs_idx.squeeze(-1)).unsqueeze(-1)
        bk = block_seq_ids[:, :kv_len].unsqueeze(1)
        allowed = allowed & (
            (kv_idx <= q_abs_idx) | ((bq == bk) & (bq >= 0))
        )
    elif causal:
        allowed = allowed & (kv_idx <= q_abs_idx)

    if window_size_left is not None:
        allowed = allowed & (
            kv_idx >= q_abs_idx - int(window_size_left)
        )
    if window_size_right is not None:
        allowed = allowed & (
            kv_idx <= q_abs_idx + int(window_size_right)
        )

    # Prefix-only masks broadcast across Q. Materialize Q rows only when
    # causal, local, or block semantics made `allowed` query-dependent.
    mask_q_len = int(allowed.shape[1])
    attn_mask = torch.zeros(
        (batch_size, 1, mask_q_len, kv_len),
        dtype=torch.float32,
        device=q.device,
    )
    attn_mask.masked_fill_(~allowed.unsqueeze(1), float("-inf"))
    return _sdpa(
        q=q,
        k=k,
        v=v,
        attn_mask=attn_mask,
        softmax_scale=softmax_scale,
    )


def flash_attn_dense_used_k_sdpa(
    q: torch.Tensor,
    k: torch.Tensor,
    v: torch.Tensor,
    seqused_k: torch.Tensor,
    softmax_scale: float,
) -> torch.Tensor:
    """Traceable dense used-K fallback with the public BSHD layout."""

    out = _dense_used_k_attention_forward(
        q=q.permute(0, 2, 1, 3),
        k=k.permute(0, 2, 1, 3),
        v=v.permute(0, 2, 1, 3),
        kv_lens=seqused_k,
        causal=False,
        window_size_left=None,
        window_size_right=None,
        softmax_scale=softmax_scale,
    )
    return out.permute(0, 2, 1, 3).contiguous()


def _paged_decode_gather_attention_forward(
    *,
    q: torch.Tensor,
    k: torch.Tensor,
    v: torch.Tensor,
    page_table: torch.Tensor,
    seqused_k: Optional[torch.Tensor],
    causal: bool,
    window_size_left: Optional[int],
    window_size_right: Optional[int],
    softmax_scale: Optional[float],
    k_scale: float,
    v_scale: float,
) -> tuple[torch.Tensor, float]:
    """Run single-token paged attention without host synchronization."""

    batch_size, max_pages_per_sequence = page_table.shape
    total_pages, page_size, num_kv_heads, head_dim = k.shape
    if v.shape[:3] != k.shape[:3]:
        raise ValueError(
            "paged decode requires K/V to share page and head dimensions"
        )
    value_head_dim = int(v.shape[3])
    if total_pages <= 0:
        raise ValueError("paged decode requires at least one physical K/V page")

    valid_pages = (page_table >= 0) & (page_table < total_pages)
    logical_page = torch.arange(
        max_pages_per_sequence,
        dtype=torch.int64,
        device=page_table.device,
    ).view(1, -1)
    # Valid pages retain logical order at the front. Invalid entries sort
    # behind them and point at page zero, where the active-K mask hides them.
    sort_keys = (
        logical_page
        + (~valid_pages).to(torch.int64) * max_pages_per_sequence
    )
    page_order = torch.argsort(sort_keys, dim=1)
    safe_page_ids = page_table.clamp(0, total_pages - 1).to(torch.int64)
    compact_page_ids = safe_page_ids.gather(1, page_order)

    k_dense = _index_select_first_dim(k, compact_page_ids.reshape(-1)).reshape(
        batch_size,
        max_pages_per_sequence * page_size,
        num_kv_heads,
        head_dim,
    )
    v_dense = _index_select_first_dim(v, compact_page_ids.reshape(-1)).reshape(
        batch_size,
        max_pages_per_sequence * page_size,
        num_kv_heads,
        value_head_dim,
    )
    available_k = valid_pages.sum(dim=1, dtype=torch.int64) * page_size
    kv_lens = (
        available_k
        if seqused_k is None
        else torch.minimum(
            seqused_k.to(device=q.device, dtype=torch.int64).clamp_min(0),
            available_k,
        )
    )

    k_dense, v_dense, q_scale, out_scale = _prepare_kv_for_sdpa(
        k=k_dense,
        v=v_dense,
        target_dtype=q.dtype,
        k_scale=k_scale,
        v_scale=v_scale,
    )
    q_sdpa = q.permute(0, 2, 1, 3)
    if q_scale != 1.0:
        q_sdpa = q_sdpa.mul(q_scale)
    out = _dense_used_k_attention_forward(
        q=q_sdpa,
        k=k_dense.permute(0, 2, 1, 3),
        v=v_dense.permute(0, 2, 1, 3),
        kv_lens=kv_lens,
        causal=causal,
        window_size_left=window_size_left,
        window_size_right=window_size_right,
        softmax_scale=softmax_scale,
    )
    return out.permute(0, 2, 1, 3), out_scale


def flash_attn_fwd_torch_fallback(
    *,
    q: torch.Tensor,
    k: torch.Tensor,
    v: torch.Tensor,
    cu_seqlens_q: Optional[torch.Tensor],
    cu_seqlens_k: Optional[torch.Tensor],
    seqused_q: Optional[torch.Tensor],
    seqused_k: Optional[torch.Tensor],
    page_table: Optional[torch.Tensor],
    softmax_scale: Optional[float],
    causal: bool,
    softcap: Optional[float] = None,
    window_size_left: Optional[int],
    window_size_right: Optional[int],
    score_mod: Optional[Callable],
    mask_mod: Optional[Callable],
    aux_tensors: Optional[list[torch.Tensor]],
    learnable_sink: Optional[torch.Tensor],
    out: torch.Tensor,
    lse: Optional[torch.Tensor],
    k_scale: float,
    v_scale: float,
) -> Tuple[torch.Tensor, Optional[torch.Tensor]]:
    if q.device.type not in ("cuda", "mps"):
        raise RuntimeError(
            "flash_attn SDPA fallback expects CUDA or MPS tensors; "
            f"got device={q.device}"
        )

    if softcap is not None:
        raise NotImplementedError("flash_attn SDPA fallback does not support softcap")
    if score_mod is not None:
        raise NotImplementedError("flash_attn SDPA fallback does not support score_mod")
    block_bidi = _is_block_bidirectional(mask_mod)
    windowed_bd = _is_windowed_blockdiag(mask_mod)
    block_seq_ids = aux_tensors[0] if (block_bidi and aux_tensors) else None
    # windowed_blockdiag carries a length-2 [window_q, window_kv] aux tensor; read it
    # as a pair of python ints (the declared pack widths, not runtime data).
    windowed_widths = None
    if windowed_bd:
        if not aux_tensors:
            raise NotImplementedError(
                "windowed_blockdiag fallback requires aux_tensors[0] ([window_q, window_kv])"
            )
        _w = aux_tensors[0]
        windowed_widths = (int(_w[0]), int(_w[1]))
        if windowed_widths[0] <= 0 or windowed_widths[1] <= 0:
            raise ValueError(
                f"windowed_blockdiag fallback needs positive window widths, got {windowed_widths}"
            )
    if aux_tensors is not None and not (block_bidi or windowed_bd):
        raise NotImplementedError("flash_attn SDPA fallback does not support aux_tensors")
    if block_bidi and block_seq_ids is None:
        raise NotImplementedError(
            "block_bidirectional fallback requires aux_tensors[0] (block_sequence_ids)"
        )
    if learnable_sink is not None:
        raise NotImplementedError("flash_attn SDPA fallback does not support learnable_sink")
    if lse is not None:
        raise NotImplementedError(
            "flash_attn SDPA fallback does not support lse outputs. "
            "The installed kestrel-kernels wheel does not include a "
            "precompiled flash-attn variant that emits lse."
        )
    if mask_mod is not None and not (block_bidi or windowed_bd):
        raise NotImplementedError(
            "flash_attn SDPA fallback only supports cute_block_bidirectional_mask "
            "and cute_windowed_blockdiag_mask"
        )
    if (block_bidi or windowed_bd) and (cu_seqlens_q is not None or cu_seqlens_k is not None):
        raise NotImplementedError(
            f"{'block_bidirectional' if block_bidi else 'windowed_blockdiag'} fallback only "
            "supports fixed-length dense or paged layouts (no cu_seqlens)"
        )
    # windowed_blockdiag is a DENSE fixed-length form only: the block-diagonal widths are
    # applied by _build_additive_attn_mask on the dense (q_lens is None) path below. The paged
    # and varlen-q (seqused_q / q_lens) branches call _attention_forward WITHOUT windowed_widths,
    # which would drop the mask and let packed windows attend across each other. Reject those
    # layouts loudly rather than silently mis-mask.
    if windowed_bd and (page_table is not None or seqused_q is not None
                        or seqused_k is not None):
        raise NotImplementedError(
            "windowed_blockdiag fallback supports only the dense fixed-length layout "
            "(no page_table, no seqused_q, no seqused_k); those branches do not apply the "
            "block-diagonal mask / do not trim K to the valid length"
        )
    is_local = window_size_left is not None or window_size_right is not None

    if q.device.type == "cuda":
        major, minor = torch.cuda.get_device_capability(q.device)
        arch_label = f"sm{major}{minor}"
    else:
        arch_label = q.device.type
    variant = "paged" if page_table is not None else "dense"
    mask_kind = (
        "block_bidirectional" if block_bidi
        else ("windowed_blockdiag" if windowed_bd
        else ("local" if is_local else ("causal" if causal else "none")))
    )
    # MPS shapes that land native Metal kernels below — emitting a
    # "falling back to torch attention" warning for paths we actually
    # accelerate would mislead anyone reading the log.
    _mps_dense_metal_path = (
        q.device.type == "mps"
        and page_table is None
        and seqused_k is None
        and not block_bidi
        and not causal
        and not is_local
        and q.dtype == torch.float16
        and q.dim() == 4
        and q.shape[-1] == 72
    )
    _mps_paged_decode_supported_mask = causal or (
        window_size_left is not None
        and (window_size_right is None or window_size_right == 0)
    )
    _mps_paged_decode_metal_path = (
        q.device.type == "mps"
        and page_table is not None
        and seqused_k is not None
        and _mps_paged_decode_supported_mask
        and q.dtype == torch.float16
        and q.dim() == 4
        and k.dim() == 4
        and v.dim() == 4
        and q.shape[1] == 1              # decode (q_len=1)
        and (
            (
                q.shape[-1] == 64
                and q.shape[2] == k.shape[2]
            )
            or (
                q.shape[-1] == 256
                and k.dtype == torch.float16
                and v.dtype == torch.float16
                and k.shape[2] > 0
                and q.shape[2] % k.shape[2] == 0
            )
        )
    )
    # Mirror the dispatch gate below — anything looser would suppress
    # warnings for true torch fallbacks (shapes the native op rejects),
    # hiding routing regressions. Skips the contiguity / stride /
    # device-equality / page-validity checks here because they need
    # the unpacked k/v/seqused_k/page_size and would have to be
    # recomputed; the broad shape gate is the cheap useful filter.
    _mps_fixed_paged_prefill_metal_path = (
        q.device.type == "mps"
        and page_table is not None
        and seqused_k is not None
        and (causal or block_bidi)
        and q.dtype == torch.float16
        and q.dim() == 4
        and k.dim() == 4
        and v.dim() == 4
        and q.shape[0] == 1              # B=1
        and q.shape[1] > 1               # prefill (q_len > 1)
        and q.shape[-1] in (64, 256)     # Moondream D64; Qwen GQA D256
        and (
            q.shape[-1] == 64
            or q.shape[1] >= _MPS_D256_PREFILL_NATIVE_MIN_Q
        )
        and k.shape[-1] == q.shape[-1]
        and v.shape[-1] == q.shape[-1]
        and k.shape[2] > 0
        and q.shape[2] % k.shape[2] == 0
        and (
            q.shape[-1] == 64
            or (k.dtype == torch.float16 and v.dtype == torch.float16)
        )
        and page_table.device == q.device
        and seqused_k.device == q.device
    )
    _mps_packed_paged_prefill_metal_path = (
        q.device.type == "mps"
        and page_table is not None
        and cu_seqlens_q is not None
        and cu_seqlens_k is None
        and seqused_k is not None
        and causal
        and not is_local
        and q.dtype == torch.float16
        and q.dim() == 3
        and k.dim() == 4
        and v.dim() == 4
        and q.shape[0] > 1               # prefill (total_q > 1)
        and k.shape[1] == 1              # native paged prefill page_size
        and q.shape[-1] in (64, 256)     # Moondream D64; Qwen GQA D256
        and (
            q.shape[-1] == 64
            or q.shape[0] >= _MPS_D256_PREFILL_NATIVE_MIN_Q
        )
        and k.shape[-1] == q.shape[-1]
        and v.shape[-1] == q.shape[-1]
        and k.shape[2] > 0
        and q.shape[1] % k.shape[2] == 0
        and (
            q.shape[-1] == 64
            or (k.dtype == torch.float16 and v.dtype == torch.float16)
        )
        and page_table.device == q.device
        and seqused_k.device == q.device
    )
    _mps_paged_prefill_metal_path = (
        _mps_fixed_paged_prefill_metal_path
        or _mps_packed_paged_prefill_metal_path
    )
    if not (
        _mps_dense_metal_path
        or _mps_paged_decode_metal_path
        or _mps_paged_prefill_metal_path
    ):
        warn_fallback_once(
            f"flash_attn_fwd_torch_attention_{variant}_{mask_kind}",
            "kestrel-kernels: falling back to torch attention for flash_attn_fwd "
            f"(arch={arch_label}, variant={variant}, mask={mask_kind}).",
        )

    out_result = out

    if cu_seqlens_q is not None or cu_seqlens_k is not None:
        if (
            page_table is None
            and cu_seqlens_q is not None
            and cu_seqlens_k is not None
            and seqused_q is None
            and seqused_k is None
            and q.dim() == 3
            and k.dim() == 3
            and v.dim() == 3
        ):
            batch_size = int(cu_seqlens_q.shape[0] - 1)
            if cu_seqlens_k.shape != (batch_size + 1,):
                raise ValueError("cu_seqlens_k must have shape [batch + 1]")
            if q.shape[0] != int(cu_seqlens_q[-1].item()):
                raise ValueError("packed q length must match cu_seqlens_q[-1]")
            if (
                k.shape[0] != int(cu_seqlens_k[-1].item())
                or v.shape[0] != int(cu_seqlens_k[-1].item())
            ):
                raise ValueError("packed k/v length must match cu_seqlens_k[-1]")

            k_fallback, v_fallback, q_scale, out_scale = _prepare_kv_for_sdpa(
                k=k,
                v=v,
                target_dtype=q.dtype,
                k_scale=k_scale,
                v_scale=v_scale,
            )
            for batch_idx in range(batch_size):
                q_start = int(cu_seqlens_q[batch_idx].item())
                q_end = int(cu_seqlens_q[batch_idx + 1].item())
                k_start = int(cu_seqlens_k[batch_idx].item())
                k_end = int(cu_seqlens_k[batch_idx + 1].item())
                q_len = q_end - q_start
                kv_len = k_end - k_start
                if q_len == 0:
                    continue
                q_sdpa = q[q_start:q_end].permute(1, 0, 2).unsqueeze(0)
                if q_scale != 1.0:
                    q_sdpa = q_sdpa.mul(q_scale)
                k_sdpa = k_fallback[k_start:k_end].permute(1, 0, 2).unsqueeze(0)
                v_sdpa = v_fallback[k_start:k_end].permute(1, 0, 2).unsqueeze(0)
                out_sdpa = _attention_forward(
                    q=q_sdpa,
                    k=k_sdpa,
                    v=v_sdpa,
                    q_len=q_len,
                    kv_len=kv_len,
                    causal=causal,
                    window_size_left=window_size_left,
                    window_size_right=window_size_right,
                    softmax_scale=softmax_scale,
                )
                if out_scale != 1.0:
                    out_sdpa = out_sdpa.mul(out_scale)
                out_result[q_start:q_end].copy_(out_sdpa.squeeze(0).permute(1, 0, 2))
            return out_result, None
        if (
            page_table is not None
            and cu_seqlens_q is not None
            and cu_seqlens_k is None
            and seqused_q is None
            and seqused_k is not None
            and q.dim() == 3
            and k.dim() == 4
            and v.dim() == 4
        ):
            batch_size = int(cu_seqlens_q.shape[0] - 1)
            if page_table.shape[0] != batch_size:
                raise ValueError("page_table batch must match cu_seqlens_q")
            if seqused_k.shape != (batch_size,):
                raise ValueError("seqused_k must have shape [batch]")
            if q.shape[0] != int(cu_seqlens_q[-1].item()):
                raise ValueError("packed q length must match cu_seqlens_q[-1]")

            page_size = int(k.shape[1])
            num_kv_heads = int(k.shape[2])
            head_dim = int(k.shape[3])
            total_pages = int(k.shape[0])
            page_ids_raw = page_table.to(dtype=torch.long)
            _k_native = k.permute(0, 2, 1, 3) if q.device.type == "mps" else None
            _v_native = v.permute(0, 2, 1, 3) if q.device.type == "mps" else None
            _float8_e4m3 = getattr(torch, "float8_e4m3fn", None)
            _mps_fp8_kv = q.device.type == "mps" and (
                (k.dtype == torch.uint8 or k.dtype == _float8_e4m3)
                and (v.dtype == torch.uint8 or v.dtype == _float8_e4m3)
            )
            _k_native_for_mps = (
                _k_native.view(torch.uint8)
                if _mps_fp8_kv and _k_native.dtype != torch.uint8
                else _k_native
            )
            _v_native_for_mps = (
                _v_native.view(torch.uint8)
                if _mps_fp8_kv and _v_native.dtype != torch.uint8
                else _v_native
            )
            _packed_out_storage_ptr = (
                out_result.untyped_storage().data_ptr()
                if q.device.type == "mps"
                else 0
            )
            _packed_aliased_with_input = q.device.type == "mps" and (
                q.untyped_storage().data_ptr() == _packed_out_storage_ptr
                or k.untyped_storage().data_ptr() == _packed_out_storage_ptr
                or v.untyped_storage().data_ptr() == _packed_out_storage_ptr
            )

            for batch_idx in range(batch_size):
                q_start = int(cu_seqlens_q[batch_idx].item())
                q_end = int(cu_seqlens_q[batch_idx + 1].item())
                q_len = q_end - q_start
                if q_len <= 0:
                    continue

                page_row = page_ids_raw[batch_idx]
                valid_pages = (page_row >= 0) & (page_row < total_pages)
                available_pages = int(valid_pages.sum().item())
                available_kv_len = available_pages * page_size
                if available_kv_len <= 0:
                    out_result[q_start:q_end].zero_()
                    continue

                kv_len = int(min(int(seqused_k[batch_idx].item()), available_kv_len))
                if kv_len <= 0:
                    out_result[q_start:q_end].zero_()
                    continue

                n_logical_pages = (kv_len + page_size - 1) // page_size
                prefix_dense = bool(valid_pages[:n_logical_pages].all().item())
                if (
                    q.device.type == "mps"
                    and q.dtype == torch.float16
                    and (k.dtype == torch.float16 or _mps_fp8_kv)
                    and (v.dtype == torch.float16 or _mps_fp8_kv)
                    and out_result.dtype == torch.float16
                    and q_len > 1
                    and causal
                    and not is_local
                    and page_size == 1
                    and head_dim in (64, 256)
                    and num_kv_heads > 0
                    and int(q.shape[1]) % num_kv_heads == 0
                    and (head_dim == 64 or not _mps_fp8_kv)
                    and (
                        head_dim == 64
                        or q_len >= _MPS_D256_PREFILL_NATIVE_MIN_Q
                    )
                    and kv_len >= q_len
                    and prefix_dense
                    and q.stride(-1) == 1
                    and out_result.stride(-1) == 1
                    and k.device == q.device
                    and v.device == q.device
                    and page_table.device == q.device
                    and seqused_k.device == q.device
                    and page_table.is_contiguous()
                    and seqused_k.is_contiguous()
                    and _k_native_for_mps.is_contiguous()
                    and _v_native_for_mps.is_contiguous()
                    and not _packed_aliased_with_input
                ):
                    q_bhld = q[q_start:q_end].unsqueeze(0).permute(0, 2, 1, 3)
                    out_bhld = (
                        out_result[q_start:q_end]
                        .unsqueeze(0)
                        .permute(0, 2, 1, 3)
                    )
                    effective_scale = (
                        softmax_scale if softmax_scale is not None
                        else 1.0 / (q.shape[-1] ** 0.5)
                    )
                    kernel_page_table = (
                        page_table[batch_idx : batch_idx + 1]
                        .to(dtype=torch.int32)
                        .contiguous()
                    )
                    kernel_seqused_k = torch.tensor(
                        [kv_len], dtype=torch.int32, device=seqused_k.device,
                    )
                    _mps_ops().paged_prefill_attn_into(
                        out_bhld,
                        q_bhld,
                        _k_native_for_mps,
                        _v_native_for_mps,
                        kernel_page_table,
                        kernel_seqused_k,
                        float(effective_scale),
                        None,
                        True,
                        float(k_scale),
                        float(v_scale),
                    )
                    continue

                pages_needed = min((kv_len + page_size - 1) // page_size, available_pages)
                page_ids = page_row[valid_pages][:pages_needed]
                k_pages = _index_select_first_dim(k, page_ids)
                v_pages = _index_select_first_dim(v, page_ids)
                k_seq = k_pages.reshape(pages_needed * page_size, num_kv_heads, head_dim)[:kv_len]
                v_seq = v_pages.reshape(pages_needed * page_size, num_kv_heads, head_dim)[:kv_len]

                k_seq, v_seq, q_scale, out_scale = _prepare_kv_for_sdpa(
                    k=k_seq,
                    v=v_seq,
                    target_dtype=q.dtype,
                    k_scale=k_scale,
                    v_scale=v_scale,
                )
                q_b = q[q_start:q_end].permute(1, 0, 2).unsqueeze(0)
                q_b_scaled = q_b if q_scale == 1.0 else q_b.mul(q_scale)
                k_b = k_seq.permute(1, 0, 2).unsqueeze(0)
                v_b = v_seq.permute(1, 0, 2).unsqueeze(0)

                out_b = _attention_forward(
                    q=q_b_scaled,
                    k=k_b,
                    v=v_b,
                    q_len=q_len,
                    kv_len=kv_len,
                    causal=causal,
                    window_size_left=window_size_left,
                    window_size_right=window_size_right,
                    softmax_scale=softmax_scale,
                )
                if out_scale != 1.0:
                    out_b = out_b.mul(out_scale)
                out_result[q_start:q_end].copy_(out_b.squeeze(0).permute(1, 0, 2))
            return out_result, None
        raise NotImplementedError(
            "kestrel-kernels fallback only supports fixed-length dense or paged attention paths used by Kestrel"
        )

    if q.dim() != 4:
        raise ValueError("fixed-length mode expects q with shape [batch, seqlen_q, heads, head_dim]")

    batch_size, q_len, num_q_heads, _head_dim = q.shape
    if seqused_q is not None:
        if seqused_q.ndim != 1 or seqused_q.shape[0] != batch_size:
            raise ValueError("seqused_q must be shape [batch] in fallback")
        q_lens = seqused_q.to(dtype=torch.int64)
        if bool((q_lens < 0).any()) or bool((q_lens > q_len).any()):
            raise ValueError("seqused_q entries must be in [0, q_len]")
    else:
        q_lens = None

    if page_table is None:
        if k.dim() != 4 or v.dim() != 4:
            raise ValueError("dense mode expects k/v with shape [batch, seqlen_k, heads_kv, head_dim]")
        kv_len = int(k.shape[1])
        if seqused_k is not None:
            if seqused_k.ndim != 1 or seqused_k.shape[0] != batch_size:
                raise ValueError("seqused_k must be shape [batch] in dense fallback")
            if seqused_k.dtype not in (torch.int32, torch.int64):
                raise ValueError("seqused_k must use an integer dtype")
            kv_lens = seqused_k
        else:
            kv_lens = None

        k_sdpa, v_sdpa, q_scale, out_scale = _prepare_kv_for_sdpa(
            k=k,
            v=v,
            target_dtype=q.dtype,
            k_scale=k_scale,
            v_scale=v_scale,
        )
        k_sdpa = k_sdpa.permute(0, 2, 1, 3)
        v_sdpa = v_sdpa.permute(0, 2, 1, 3)
        if q_lens is None:
            q_sdpa = q.permute(0, 2, 1, 3)
            q_sdpa_scaled = q_sdpa if q_scale == 1.0 else q_sdpa.mul(q_scale)

            # MPS dense self-attn shortcut: vision encoder shape (head_dim=72,
            # bf16, no mask, no causal, q_len == kv_len) lands the native
            # ``_mps_ops().flash_attn_dense_into`` Metal kernel
            # (MLX steel attention lift). ~5× per-call vs torch SDPA at
            # SigLIP shapes; the fallback path below is what every other
            # case (head_dim != 72, masked, causal, GQA, non-stride-1 last
            # axis) still uses.
            #
            # The kernel requires ``stride(-1) == 1`` on Q/K/V/out (the
            # head_dim axis is loaded vectorized). ``q_sdpa`` /
            # ``k_sdpa`` / ``v_sdpa`` are produced by ``permute(0,2,1,3)``
            # of the inputs, and ``out_view`` is the same permute of
            # ``out_result``; for sliced or otherwise non-stride-1
            # last-axis views the predicate falls back to torch SDPA so
            # we never trip the C++ ``TORCH_CHECK``. The kernel also
            # writes ``out`` while still reading Q/K/V — if a caller
            # aliases ``out`` with any of them (e.g. reuses ``q`` as
            # ``out``), the writes would corrupt later reads, so we
            # defensively reject any storage overlap and fall through
            # to the SDPA path that materializes its output into a
            # disjoint temporary.
            _out_storage_ptr = out_result.untyped_storage().data_ptr()
            _aliased_with_input = (
                q_sdpa.untyped_storage().data_ptr() == _out_storage_ptr
                or k_sdpa.untyped_storage().data_ptr() == _out_storage_ptr
                or v_sdpa.untyped_storage().data_ptr() == _out_storage_ptr
            )
            if (
                q.device.type == "mps"
                and not block_bidi
                and not windowed_bd
                and not causal
                and not is_local
                and kv_lens is None
                and q.dtype == torch.float16
                and q.shape[-1] == 72
                and q_len == kv_len
                and num_q_heads == int(k_sdpa.shape[1])
                and q_sdpa.stride(-1) == 1
                and k_sdpa.stride(-1) == 1
                and v_sdpa.stride(-1) == 1
                and out_result.stride(-1) == 1
                and not _aliased_with_input
            ):
                effective_scale = (
                    softmax_scale if softmax_scale is not None
                    else 1.0 / (q.shape[-1] ** 0.5)
                )
                # ``q_scale`` is a per-tensor pre-softmax score scaling
                # (see ``_prepare_kv_for_sdpa``). Folding it into the
                # softmax temperature instead of materializing
                # ``q_sdpa.mul(q_scale)`` saves an alloc + a full Q
                # multiply per call. Same applies to writing into
                # ``out_result.permute(0,2,1,3)`` directly: the Metal op
                # supports arbitrary strides on the first three axes
                # (only D needs stride-1), so we skip the temporary
                # ``[B, H, L, D]`` output + post-permute copy.
                effective_scale *= q_scale
                out_view = out_result.permute(0, 2, 1, 3)
                _mps_ops().flash_attn_dense_into(
                    out_view, q_sdpa, k_sdpa, v_sdpa, effective_scale,
                    None, False,
                )
                if out_scale != 1.0:
                    out_result.mul_(out_scale)
                return out_result, None

            if kv_lens is not None:
                out_sdpa = _dense_used_k_attention_forward(
                    q=q_sdpa_scaled,
                    k=k_sdpa,
                    v=v_sdpa,
                    kv_lens=kv_lens,
                    causal=causal,
                    window_size_left=window_size_left,
                    window_size_right=window_size_right,
                    softmax_scale=softmax_scale,
                    block_seq_ids=block_seq_ids if block_bidi else None,
                )
                if out_scale != 1.0:
                    out_sdpa = out_sdpa.mul(out_scale)
                out_result.copy_(out_sdpa.permute(0, 2, 1, 3))
            elif block_bidi:
                for b in range(batch_size):
                    block_seq_ids_b = (
                        block_seq_ids[b]
                        if block_seq_ids.ndim == 2
                        else block_seq_ids
                    )
                    out_b = _attention_forward(
                        q=q_sdpa_scaled[b : b + 1],
                        k=k_sdpa[b : b + 1],
                        v=v_sdpa[b : b + 1],
                        q_len=q_len,
                        kv_len=kv_len,
                        causal=causal,
                        window_size_left=window_size_left,
                        window_size_right=window_size_right,
                        softmax_scale=softmax_scale,
                        block_seq_ids=block_seq_ids_b,
                    )
                    if out_scale != 1.0:
                        out_b = out_b.mul(out_scale)
                    out_result[b : b + 1].copy_(out_b.permute(0, 2, 1, 3))
            else:
                # windowed_blockdiag: position-only block-diagonal bias, identical
                # for every batch element (the windows are packed the same way), so
                # SDPA applies the single [1,1,q_len,kv_len] mask over the whole batch.
                out_sdpa = _attention_forward(
                    q=q_sdpa_scaled,
                    k=k_sdpa,
                    v=v_sdpa,
                    q_len=q_len,
                    kv_len=kv_len,
                    causal=causal,
                    window_size_left=window_size_left,
                    window_size_right=window_size_right,
                    softmax_scale=softmax_scale,
                    windowed_widths=windowed_widths,
                )
                if out_scale != 1.0:
                    out_sdpa = out_sdpa.mul(out_scale)
                out_result.copy_(out_sdpa.permute(0, 2, 1, 3))
        else:
            out_result.zero_()
            q_sdpa_all = q.permute(0, 2, 1, 3)
            for b in range(batch_size):
                q_len_b = int(q_lens[b].item())
                if q_len_b <= 0:
                    continue
                kv_len_b = (
                    int(kv_lens[b].item())
                    if kv_lens is not None
                    else kv_len
                )
                if kv_len_b <= 0:
                    continue
                q_b = q_sdpa_all[b : b + 1, :, :q_len_b, :]
                q_b_scaled = q_b if q_scale == 1.0 else q_b.mul(q_scale)
                block_seq_ids_b = (
                    block_seq_ids[b]
                    if (
                        block_bidi
                        and block_seq_ids is not None
                        and block_seq_ids.ndim == 2
                    )
                    else block_seq_ids
                )
                out_b = _attention_forward(
                    q=q_b_scaled,
                    k=k_sdpa[b : b + 1, :, :kv_len_b, :],
                    v=v_sdpa[b : b + 1, :, :kv_len_b, :],
                    q_len=q_len_b,
                    kv_len=kv_len_b,
                    causal=causal,
                    window_size_left=window_size_left,
                    window_size_right=window_size_right,
                    softmax_scale=softmax_scale,
                    block_seq_ids=block_seq_ids_b,
                )
                if out_scale != 1.0:
                    out_b = out_b.mul(out_scale)
                out_result[b : b + 1, :q_len_b].copy_(out_b.permute(0, 2, 1, 3))
    else:
        if k.dim() != 4 or v.dim() != 4:
            raise ValueError("paged mode expects k/v with shape [num_pages, page_size, heads_kv, head_dim]")
        page_size = int(k.shape[1])
        num_kv_heads = int(k.shape[2])
        head_dim = int(k.shape[3])
        total_pages = int(k.shape[0])

        # MPS paged decode shortcut: single-query causal/sliding-window
        # attention with paged KV at Moondream 2 text-decoder shape
        # (head_dim=64, no GQA, fp16 q/out with fp16 or FP8 KV), Qwen 3.5
        # full-attention shape, or Gemma 4 sliding-attention shape
        # (head_dim=256, GQA, fp16 q/out/KV) lands the native
        # ``_mps_ops().paged_decode_attn_into``
        # Metal kernel — 8–22× faster than the per-batch index_select +
        # SDPA loop below, scaling sub-linearly with kv_len. Falls through
        # to the loop for prefill (q_len > 1) or any model shape the
        # kernel doesn't yet handle.
        #
        # Contiguity gate: kestrel passes ``k_cache.permute(0, 2, 1, 3)``
        # (production ``(N, H, P, D)`` storage → ``(N, P, H, D)`` view).
        # The native kernel needs the production layout back, so we
        # re-permute. For ``page_size = 1`` (production prefix-cache
        # requirement) the round-trip restores a contiguous view; for
        # ``page_size > 1`` from a tensor that wasn't originally
        # ``(N, H, P, D)``-contiguous, the re-permute yields a strided
        # view and we fall through to the torch path rather than
        # raising the kernel's contiguity TORCH_CHECK.
        _k_native = k.permute(0, 2, 1, 3) if (q.device.type == "mps") else None
        _v_native = v.permute(0, 2, 1, 3) if (q.device.type == "mps") else None
        _float8_e4m3 = getattr(torch, "float8_e4m3fn", None)
        _mps_fp8_kv = q.device.type == "mps" and (
            (k.dtype == torch.uint8 or k.dtype == _float8_e4m3)
            and (v.dtype == torch.uint8 or v.dtype == _float8_e4m3)
        )
        _k_native_for_mps = (
            _k_native.view(torch.uint8)
            if _mps_fp8_kv and _k_native.dtype != torch.uint8
            else _k_native
        )
        _v_native_for_mps = (
            _v_native.view(torch.uint8)
            if _mps_fp8_kv and _v_native.dtype != torch.uint8
            else _v_native
        )
        _mps_paged_decode_native_shape = (
            (
                q.shape[-1] == 64
                and num_q_heads == num_kv_heads
            )
            or (
                q.shape[-1] == 256
                and num_kv_heads > 0
                and num_q_heads % num_kv_heads == 0
                and k.dtype == torch.float16
                and v.dtype == torch.float16
            )
        )
        _mps_paged_decode_supported_mask = causal or (
            window_size_left is not None
            and (window_size_right is None or window_size_right == 0)
        )
        # Native dispatch predicate. The kernel takes per-axis strides
        # for q/out (see ``sdpa_vector_paged`` in
        # ``mlx/backend/metal/kernels/sdpa_vector.h``), so q/out only
        # need ``stride(-1) == 1`` (head_dim contiguous). Anything else
        # the kernel would actually reject — fp16, supported head dims,
        # page-table/seqused_k contiguous, etc. — we fail loudly below
        # if a supported decode shape lands here but misses the native
        # gate. No silent torch-SDPA fallback for hot MPS decode shapes.
        if (
            q.device.type == "mps"
            and q.dtype == torch.float16
            and (k.dtype == torch.float16 or _mps_fp8_kv)
            and (v.dtype == torch.float16 or _mps_fp8_kv)
            and out_result.dtype == torch.float16
            and q_len == 1
            and q_lens is None
            and _mps_paged_decode_supported_mask
            and _mps_paged_decode_native_shape
            and (q.shape[-1] == 64 or not _mps_fp8_kv)
            and seqused_k is not None
            and q.stride(-1) == 1
            and out_result.stride(-1) == 1
            and page_table.is_contiguous()
            and seqused_k.is_contiguous()
            and _k_native_for_mps.is_contiguous()
            and _v_native_for_mps.is_contiguous()
        ):
            effective_scale = (
                softmax_scale if softmax_scale is not None
                else 1.0 / (q.shape[-1] ** 0.5)
            )
            _mps_ops().paged_decode_attn_into(
                out_result,
                q,
                _k_native_for_mps,
                _v_native_for_mps,
                page_table.to(dtype=torch.int32),
                seqused_k.to(dtype=torch.int32),
                float(effective_scale),
                float(k_scale),
                float(v_scale),
                -1 if window_size_left is None else int(window_size_left),
            )
            return out, None
        elif (
            q.device.type == "mps"
            and q_len == 1
            and _mps_paged_decode_supported_mask
            and _mps_paged_decode_native_shape
        ):
            # Supported MPS decode shapes that can't take the native
            # kernel should still fail loudly. Falling through to the
            # per-batch torch SDPA loop here is 3–12× slower per step
            # at B>1 and has historically masked correctness bugs
            # (e.g. non-contiguous q from QKV split silently regressing
            # into the loop and tanking decode throughput).
            raise NotImplementedError(
                f"MPS paged decode requires the native kernel for "
                f"supported decode shapes: got q.shape={tuple(q.shape)} "
                f"q.stride={q.stride()} q.dtype={q.dtype} "
                f"num_q_heads={num_q_heads} num_kv_heads={num_kv_heads} "
                f"k_scale={k_scale} v_scale={v_scale}. Verify the "
                f"conditions above (fp16 q/out, fp16 or supported FP8 KV, "
                f"head_dim in {{64, 256}}, causal or left-window decode, "
                f"page_table contiguous, "
                f"q/out stride(-1)==1)."
            )

        # MPS paged prefill shortcut: multi-query attention with paged
        # KV at Moondream 2 text-decoder shape (head_dim=64, no GQA,
        # fp16 q/out with fp16 or FP8 KV) and the Qwen full-attention
        # prefill shape (head_dim=256, GQA, fp16 KV), page_size=1,
        # causal or block-bidirectional mask. Lands the
        # native ``_mps_ops().paged_prefill_attn_into`` Metal
        # kernel — same MLX steel-attention math as ``flash_attn_dense_into``
        # but with K/V loaded via page-table indirection instead of a
        # host-side ``index_select`` + ``contiguous()`` round-trip.
        # Per-batch ``seqused_k`` and out-of-range page IDs are handled
        # inside the kernel (zeroed rows). Falls through to the torch
        # path for D=72 (no paged-vision use today), D=256 FP8 KV, or
        # shapes the kernel doesn't yet specialize.
        _k_native = k.permute(0, 2, 1, 3) if (q.device.type == "mps") else None
        _v_native = v.permute(0, 2, 1, 3) if (q.device.type == "mps") else None
        # The kernel writes ``out`` while still reading Q/K/V — if a
        # caller aliases ``out`` with any of them (e.g. reuses ``q``
        # as ``out``), the writes would corrupt later reads. Defensively
        # reject storage overlap and fall through to the torch path
        # that materializes into a disjoint temporary. Mirrors the
        # dense Metal shortcut's guard above.
        _paged_out_storage_ptr = (
            out_result.untyped_storage().data_ptr()
            if q.device.type == "mps"
            else 0
        )
        _paged_aliased_with_input = q.device.type == "mps" and (
            q.untyped_storage().data_ptr() == _paged_out_storage_ptr
            or k.untyped_storage().data_ptr() == _paged_out_storage_ptr
            or v.untyped_storage().data_ptr() == _paged_out_storage_ptr
        )
        if (
            q.device.type == "mps"
            and q.dtype == torch.float16
            and (k.dtype == torch.float16 or _mps_fp8_kv)
            and (v.dtype == torch.float16 or _mps_fp8_kv)
            and out_result.dtype == torch.float16
            and q_len > 1
            and q_lens is None
            and (causal or block_bidi)
            and batch_size == 1
            and page_size == 1
            and head_dim in (64, 256)
            and num_kv_heads > 0
            and num_q_heads % num_kv_heads == 0
            and (head_dim == 64 or not _mps_fp8_kv)
            and (
                head_dim == 64
                or q_len >= _MPS_D256_PREFILL_NATIVE_MIN_Q
            )
            and seqused_k is not None
            and page_table.is_contiguous()
            and seqused_k.is_contiguous()
            and _k_native_for_mps.is_contiguous()
            and _v_native_for_mps.is_contiguous()
            # The native op's TORCH_CHECK requires stride-1 on the
            # head_dim axis of both q and out. Sliced last-dim inputs
            # would hard-fail; gate them out so they fall through to
            # the torch path instead.
            and q.stride(-1) == 1
            and out_result.stride(-1) == 1
            # All metadata tensors must be on the same device as q —
            # the C++ op's same-device TORCH_CHECK would otherwise
            # hard-fail on a CPU page_table or seqused_k paired with
            # MPS q/k/v.
            and k.device == q.device
            and v.device == q.device
            and page_table.device == q.device
            and seqused_k.device == q.device
            and not _paged_aliased_with_input
        ):
            # Pass strided views directly — the kernel reads strides for
            # the first three axes from ``params->{Q,O}_strides`` and only
            # requires stride-1 on the last (D) axis. Avoiding the
            # ``permute().contiguous()`` copy + ``empty_like`` allocation +
            # final ``copy_`` saves ~6 MB × 2 round-trip per call (Exp 3).
            q_bhld = q.permute(0, 2, 1, 3)
            out_bhld = out_result.permute(0, 2, 1, 3)

            effective_scale = (
                softmax_scale if softmax_scale is not None
                else 1.0 / (q.shape[-1] ** 0.5)
            )

            # Clamp ``seqused_k[0]`` to the count of *valid* page-table
            # entries. The kernel iterates over
            # ``page_table[0, 0..ceil(kL_real / page_size))`` and the
            # paged loader zero-fills rows for invalid page IDs — those
            # zero rows still participate in softmax normalization and
            # would silently skew the output if seqused_k is stale or
            # oversized. Mirrors the prior (gather+dense) path's
            # ``available_pages``-based clamp.
            page_row = page_table[0]
            valid_pages = (page_row >= 0) & (page_row < total_pages)
            available_pages = int(valid_pages.sum().item())
            kv_len_b = min(
                int(seqused_k[0].item()), available_pages * page_size,
            )
            if kv_len_b <= 0:
                # Empty/all-invalid KV: the kernel can't normalize over
                # zero kv positions (NaN softmax) and a zero-width
                # prefix-LM mask trips the dispatcher's qL check. Zero
                # the output and return — caller sees a row of zeros,
                # matching the prior path's implicit no-op behavior.
                out_result.zero_()
                return out, None

            # The kernel reads ``page_table[0, 0..ceil(kv_len_b/page_size))``
            # in order — invalid IDs in the active prefix get
            # zero-filled, but later valid pages then get skipped (the
            # kernel only iterates ``kv_len_b`` rows). Production
            # always fills page_table densely, so this only diverges
            # from the prior compacted-gather path under stale/sparse
            # state. Fall through to the torch path in that case.
            n_logical_pages = (kv_len_b + page_size - 1) // page_size
            prefix_dense = bool(
                valid_pages[:n_logical_pages].all().item()
            )
            if kv_len_b >= q_len and prefix_dense:
                # Production normal prefill always has kv_len >= qL.
                # When kv_len < qL (only in stale/undersized cache
                # states) ``qL_off_local = kL_real - qL`` goes negative
                # for early Q rows, the causal branch masks every
                # column for those rows, and softmax produces NaN —
                # fall through to the torch path in that case.
                kernel_seqused_k = torch.tensor(
                    [kv_len_b], dtype=torch.int32, device=seqused_k.device,
                )

                if block_bidi:
                    mask = _get_block_bidi_mask(
                        block_seq_ids[0], q_len, kv_len_b, q.device, q.dtype,
                    )
                    causal_flag = False
                else:
                    mask = None
                    causal_flag = True

                _mps_ops().paged_prefill_attn_into(
                    out_bhld,
                    q_bhld,
                    _k_native_for_mps,
                    _v_native_for_mps,
                    page_table.to(dtype=torch.int32),
                    kernel_seqused_k,
                    float(effective_scale),
                    mask,
                    causal_flag,
                    float(k_scale),
                    float(v_scale),
                )
                return out, None
            # kv_len_b < q_len OR sparse page_table prefix → fall
            # through to the torch path below (which compacts via
            # ``index_select(valid_pages)``).
        elif q.device.type == "mps" and q_len > 1 and _mps_fp8_kv:
            raise NotImplementedError(
                "MPS FP8 paged prefill requires the native kernel "
                "(fp16 q/out, FP8 KV, B=1, page_size=1, head_dim=64, no GQA, "
                "contiguous page_table/seqused_k, dense valid page prefix)."
            )

        if q_len == 1 and q_lens is None:
            out_decode, out_scale = _paged_decode_gather_attention_forward(
                q=q,
                k=k,
                v=v,
                page_table=page_table,
                seqused_k=seqused_k,
                causal=causal,
                window_size_left=window_size_left,
                window_size_right=window_size_right,
                softmax_scale=softmax_scale,
                k_scale=k_scale,
                v_scale=v_scale,
            )
            if out_scale != 1.0:
                out_decode = out_decode.mul(out_scale)
            out_result.copy_(out_decode)
            return out, None

        # Variable-length prefill compacts each request independently. Unlike
        # decode, its row lengths determine output slices, so it is not used
        # during fixed-shape CUDA graph capture.
        if q_len > 0:
            if q_lens is not None:
                out_result.zero_()
            page_ids_raw = page_table.to(dtype=torch.long)

            for b in range(batch_size):
                q_len_b = int(q_lens[b].item()) if q_lens is not None else q_len
                if q_len_b <= 0:
                    continue
                q_b = q[b : b + 1, :q_len_b].permute(0, 2, 1, 3)
                page_row = page_ids_raw[b]
                valid_pages = (page_row >= 0) & (page_row < total_pages)
                available_pages = int(valid_pages.sum().item())
                available_kv_len = available_pages * page_size
                if available_kv_len <= 0:
                    out_result[b : b + 1].zero_()
                    continue

                if seqused_k is not None:
                    kv_len = int(min(int(seqused_k[b].item()), available_kv_len))
                else:
                    kv_len = available_kv_len

                if kv_len <= 0:
                    out_result[b : b + 1].zero_()
                    continue

                pages_needed = min((kv_len + page_size - 1) // page_size, available_pages)
                page_ids = page_row[valid_pages][:pages_needed]

                k_pages = _index_select_first_dim(k, page_ids)
                v_pages = _index_select_first_dim(v, page_ids)
                k_seq = k_pages.reshape(pages_needed * page_size, num_kv_heads, head_dim)[:kv_len]
                v_seq = v_pages.reshape(pages_needed * page_size, num_kv_heads, head_dim)[:kv_len]

                k_seq, v_seq, q_scale, out_scale = _prepare_kv_for_sdpa(
                    k=k_seq,
                    v=v_seq,
                    target_dtype=q.dtype,
                    k_scale=k_scale,
                    v_scale=v_scale,
                )
                k_b = k_seq.permute(1, 0, 2).unsqueeze(0)
                v_b = v_seq.permute(1, 0, 2).unsqueeze(0)
                q_b_scaled = q_b if q_scale == 1.0 else q_b.mul(q_scale)

                out_b = _attention_forward(
                    q=q_b_scaled,
                    k=k_b,
                    v=v_b,
                    q_len=q_len_b,
                    kv_len=kv_len,
                    causal=causal,
                    window_size_left=window_size_left,
                    window_size_right=window_size_right,
                    softmax_scale=softmax_scale,
                    block_seq_ids=block_seq_ids[b] if block_bidi else None,
                )
                if out_scale != 1.0:
                    out_b = out_b.mul(out_scale)
                out_result[b : b + 1, :q_len_b].copy_(out_b.permute(0, 2, 1, 3))

            return out, None

    return out, None
